select m.id,v.k,v.t,v.ft,v.r,v.s,v.o::jsonb from platform_modules m cross join (values
('search-code','کد جستجو','text',true,10,'{}'),('search-title','عنوان جستجو','text',true,20,'{}'),('query','عبارت جستجو','text',false,30,'{}'),('document-code','کد سند','text',false,40,'{}'),('document-type','نوع سند','select',false,50,'{"options":["دستورالعمل","آیین‌نامه","فرآیند","راهنما","خط‌مشی","قرارداد","گزارش","صورتجلسه","فرم","سایر"]}'),('folder','پوشه','text',false,60,'{}'),('tags','برچسب‌ها','text',false,70,'{}'),('owner','مالک','text',false,80,'{}'),('access-level','سطح دسترسی','select',false,90,'{"options":["عمومی","کاربران واردشده","نقش‌محور","سازمانی","محرمانه"]}'),('date-from','از تاریخ','text',false,100,'{}'),('date-to','تا تاریخ','text',false,110,'{}'),('version','نسخه','number',false,120,'{}'),('status','وضعیت سند','select',false,130,'{"options":["پیش‌نویس","فعال","نیازمند بازبینی","منسوخ","بایگانی شده"]}'),('sort-by','مرتب‌سازی بر اساس','select',true,140,'{"options":["ارتباط","تاریخ جدیدتر","تاریخ قدیمی‌تر","عنوان","کد سند"]}'),('result-limit','حد نتایج','number',true,150,'{}'),('saved-search','جستجوی ذخیره‌شده','select',true,160,'{"options":["خیر","بله"]}'),('description','توضیحات','textarea',false,170,'{}'),('notes','یادداشت','textarea',false,180,'{}')
) v(k,t,ft,r,s,o) where m.code='44-document-search' on conflict(module_id,field_key) do update set title=excluded.title,field_type=excluded.field_type,required=excluded.required,sort_order=excluded.sort_order,options=excluded.options;
