insert into platform_modules(code,title,is_active) values ('44-document-search','جستجو و بایگانی هوشمند مستندات',true) on conflict(code) do update set title=excluded.title,is_active=true;
insert into module_field_definitions(module_id,field_key,title,field_type,required,sort_order,options)
insert into module_actions(module_id,action_code,title,permission) select m.id,v.a,v.t,v.p from platform_modules m cross join (values
('read','مشاهده جستجوها','modules:44-document-search:read'),('write','ثبت جستجو','modules:44-document-search:write'),('delete','حذف جستجو','modules:44-document-search:delete'),('search','اجرای جستجو','modules:44-document-search:search'),('save','ذخیره جستجو','modules:44-document-search:save'),('duplicate','تکثیر جستجو'),('clear','پاک‌سازی فیلترها','modules:44-document-search:clear')) v(a,t,p) where m.code='44-document-search' on conflict(module_id,action_code) do update set title=excluded.title,permission=excluded.permission;